using System;using System.IO;using System.IO.Pipes;using System.Text;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;using System.Web.Script.Serialization;
static class BoardTransport {
 internal static string Pipe {get{return CaptureInboxTransport.Pipe+".Board";}}
 internal static bool Valid(string command){return new[]{"--board","--board-new","--board-recent","--board-library"}.Contains(command);}
 internal static bool Forward(string command){if(!Valid(command))return false;try{using(var pipe=new NamedPipeClientStream(".",Pipe,PipeDirection.InOut)){pipe.Connect(900);using(var writer=new StreamWriter(pipe,new UTF8Encoding(false),1024,true)){writer.AutoFlush=true;writer.WriteLine(command);using(var reader=new StreamReader(pipe,Encoding.UTF8,false,1024,true)){var reply=reader.ReadLineAsync();return reply.Wait(1200)&&reply.Result=="board-ready";}}}}catch{return false;}}
}
sealed partial class WorldWindow {
 NamedPipeServerStream boardListener;
 void StartBoardCommands(){FormClosed+=(s,e)=>{if(boardListener!=null)boardListener.Dispose();};Task.Run(()=>{while(!closing){try{using(var server=new NamedPipeServerStream(BoardTransport.Pipe,PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous)){boardListener=server;server.WaitForConnection();using(var reader=new StreamReader(server,Encoding.UTF8,false,1024,true))using(var writer=new StreamWriter(server,new UTF8Encoding(false),1024,true)){string command=reader.ReadLine();if(!BoardTransport.Valid(command))continue;writer.WriteLine("board-ready");writer.Flush();BeginInvoke((Action)(async()=>await OpenBoardCommand(command,false)));}}}catch{if(closing)return;System.Threading.Thread.Sleep(200);}}});}

 async Task<bool> FlushBoard(){string token=Guid.NewGuid().ToString("N");var done=new TaskCompletionSource<bool>();EventHandler<Microsoft.Web.WebView2.Core.CoreWebView2WebMessageReceivedEventArgs> handler=null;handler=(s,e)=>{try{if(!JagoHostSecurity.Trusted(e.Source,"https://jagolibrary.example/index.html"))return;var d=new JavaScriptSerializer().Deserialize<System.Collections.Generic.Dictionary<string,object>>(e.WebMessageAsJson);if(Convert.ToString(d["type"])=="board-flushed"&&Convert.ToString(d["token"])==token)done.TrySetResult(Convert.ToBoolean(d["ok"]));}catch{}};browser.CoreWebView2.WebMessageReceived+=handler;try{await browser.CoreWebView2.ExecuteScriptAsync("(async()=>{let ok=!!window.JagoBoard?.active && await JagoBoard.flush();chrome.webview.postMessage({type:'board-flushed',token:'"+token+"',ok});})()");if(await Task.WhenAny(done.Task,Task.Delay(6000))==done.Task)return await done.Task;return false;}finally{browser.CoreWebView2.WebMessageReceived-=handler;}}
 async Task OpenBoardCommand(string command,bool restore){try{for(int i=0;i<150;i++){if(ready&&await browser.CoreWebView2.ExecuteScriptAsync("!!window.JagoBoard")=="true")break;await Task.Delay(100);}if(command=="--board-library"){await browser.CoreWebView2.ExecuteScriptAsync("document.getElementById('boardQuickLibrary').click()");}else{await browser.CoreWebView2.ExecuteScriptAsync("JagoBoard.open({restore:"+(restore?"true":"false")+",newBoard:"+(command=="--board-new"?"true":"false")+"}).then(()=>{"+(command=="--board-recent"?"document.getElementById('boardQuickChoose').focus();":"")+"})");}if(WindowState==FormWindowState.Minimized)WindowState=FormWindowState.Normal;Show();Activate();string owner=Environment.GetEnvironmentVariable("JAGO_WORKSPACE_ROOT"),tab=Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TAB_ID");if(owner!=null&&tab!=null)System.IO.File.WriteAllText(System.IO.Path.Combine(owner,"action-"+Guid.NewGuid()+".json"),new JavaScriptSerializer().Serialize(new{action="focus",id=tab}));}catch(Exception e){ManagedPost(new{type="error",message="Board: "+e.Message});}}
}
